// Package entiredir owns access to the repository's .entire directory.
//
// Every non-test read and write under .entire goes through the single *os.Root
// this package hands out, rather than through an absolute path assembled by the
// caller. Two properties follow from that, and neither survives if a call site
// reverts to os.ReadFile/os.WriteFile on a joined path:
//
//   - Containment. .entire holds paths named from agent-supplied session IDs,
//     tool-use IDs, and tree paths. A root confines every open to the directory
//     at the kernel level, so a crafted name cannot escape it, and a symlink
//     swapped in between resolution and open (TOCTOU) surfaces as an error
//     rather than a redirected write.
//   - One directory handle per worktree. The root is opened once and memoized,
//     so the hot hook paths stop paying an OpenRoot per state file, and every
//     consumer observes the same directory even if .entire is renamed or
//     replaced underneath a long-running process.
//
// Creation is deliberately lazy and split across two entry points. Open creates
// .entire because its callers are about to write; OpenForRead never creates,
// because a command that only looks must leave an untouched repo untouched.
// That distinction is load-bearing for logging in particular: the log file is
// created by the first line actually written, so a command that logs nothing
// (completion, version, help) must not leave an .entire behind.
//
// Reset exists for the paths that delete the directory (entire disable,
// entire clean) and for tests. A cached root that outlives its directory is a
// handle to an unlinked inode: writes through it succeed and land nowhere.
package entiredir

import (
	"context"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
	"github.com/entireio/cli/cmd/entire/cli/osroot"
	"github.com/entireio/cli/cmd/entire/cli/paths"
)

// dirPerm is the mode .entire is created with. It matches the mode the
// directory already had when each consumer created its own subdirectory.
const dirPerm = 0o750

// ReadFile reads an Entire-owned file without following a symlink at the leaf.
func ReadFile(root *os.Root, name string) ([]byte, error) {
	return osroot.ReadFileNoFollow(root, name) //nolint:wrapcheck // preserve os error classification
}

// WriteFile atomically replaces an Entire-owned file. Renaming a newly-created
// temporary file over name replaces a planted leaf symlink rather than opening
// and truncating its target.
func WriteFile(root *os.Root, name string, data []byte, perm os.FileMode) error {
	return jsonutil.WriteFileAtomicIn(root, name, data, perm) //nolint:wrapcheck // caller supplies path context
}

// Open returns the shared *os.Root for the current worktree's .entire
// directory, creating the directory if it does not exist. Use it from write
// paths; read-only callers want OpenForRead.
//
// The returned root is owned by this package and shared with every other
// caller. Do not close it.
func Open(ctx context.Context) (*os.Root, error) {
	worktreeRoot, err := anchor(ctx)
	if err != nil {
		return nil, err
	}
	return OpenAt(worktreeRoot)
}

// OpenForRead is Open without creating .entire. A missing directory is
// reported as fs.ErrNotExist, which callers classify with errors.Is.
func OpenForRead(ctx context.Context) (*os.Root, error) {
	worktreeRoot, err := anchor(ctx)
	if err != nil {
		return nil, err
	}
	return OpenAtForRead(worktreeRoot)
}

// OpenAt is Open for an explicit worktree root, for the callers that already
// resolved one (or that act on a worktree other than the current directory).
func OpenAt(worktreeRoot string) (*os.Root, error) {
	return open(worktreeRoot, true)
}

// OpenAtForRead is OpenForRead for an explicit worktree root.
func OpenAtForRead(worktreeRoot string) (*os.Root, error) {
	return open(worktreeRoot, false)
}

// Opener returns a thunk that calls Open when invoked, for consumers that are
// handed their storage up front but must not touch the disk until they first
// write (see logging.Config.Root).
func Opener(ctx context.Context) func() (*os.Root, error) {
	return func() (*os.Root, error) { return Open(ctx) }
}

// OpenerAt returns a thunk that calls OpenAt when invoked.
func OpenerAt(worktreeRoot string) func() (*os.Root, error) {
	return func() (*os.Root, error) { return OpenAt(worktreeRoot) }
}

// Path returns the absolute path of the current worktree's .entire directory.
// It is for messages and for the few consumers that must hand a path to an
// external process; it is not an invitation to do I/O on the result.
func Path(ctx context.Context) (string, error) {
	worktreeRoot, err := anchor(ctx)
	if err != nil {
		return "", err
	}
	return filepath.Join(worktreeRoot, paths.EntireDir), nil
}

// Reset closes and forgets every cached root. Call it after deleting .entire:
// a root cached across the deletion refers to an unlinked directory, so writes
// through it succeed and land nowhere.
//
// The registry is shared with the other anchors, so this clears them too. That
// is the behaviour teardown wants — a repo whose .entire just went away is not a
// repo whose .git root is worth keeping — and tests get one reset to call.
func Reset() {
	osroot.ResetShared()
}

// Name converts a repo-relative path under .entire (for example
// paths.EntireTmpDir) to a name relative to the .entire root. The repo-relative
// constants stay as they are because git paths, settings display, and gitignore
// entries all need them; this is the one-line bridge to root-relative I/O.
//
// A path outside .entire is an error rather than a silent passthrough: the
// alternative is a name that resolves inside .entire but means something else.
func Name(repoRelPath string) (string, error) {
	cleaned := filepath.ToSlash(filepath.Clean(filepath.FromSlash(repoRelPath)))
	if cleaned == paths.EntireDir {
		return ".", nil
	}
	rest, ok := strings.CutPrefix(cleaned, paths.EntireDir+"/")
	if !ok || rest == "" {
		return "", fmt.Errorf("%q is not under %s", repoRelPath, paths.EntireDir)
	}
	return rest, nil
}
package agent

import (
	"fmt"
	"os"
	"path"
	"path/filepath"

	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
	"github.com/entireio/cli/cmd/entire/cli/osroot"
	"github.com/entireio/cli/cmd/entire/cli/worktreedir"
)

// HookConfigFile is an agent's hook-configuration file inside the worktree —
// .claude/settings.json, .cursor/hooks.json, .gemini/settings.json,
// .github/hooks/entire.json, .factory/settings.json, .codex/hooks.json,
// .opencode/plugins/entire.ts, .pi/extensions/entire/index.ts.
//
// Eight agents each carried the same four lines: filepath.Join a repo root with
// a fixed relative path, then os.ReadFile / os.MkdirAll / os.WriteFile /
// os.Remove on the result, each with a //nolint:gosec saying the path came from
// the repo root. That justification is about where the path was BUILT and says
// nothing about where it RESOLVES, which is the part that matters: `.claude` and
// its siblings live in the working tree, and a working tree arrives by clone.
// A repository carrying a checked-in symlink at `.claude` therefore had
// `entire enable` create directories and write JSON through it, to wherever it
// pointed — outside the repository included.
//
// Anchoring on worktreedir fixes that at the root rather than at each call site:
// the base is the worktree root, the agent's fixed subpath is a NAME inside it,
// and directories are created with MkdirAllNoSymlink so a symlinked component is
// refused by name instead of silently followed. It also collapses the eight
// copies into one, which is what keeps the next agent integration from
// reintroducing the pattern. Pi was the one that got left behind on the first
// pass and had to be migrated afterwards, which is the argument for routing a
// new agent through here rather than for trusting that someone will notice.
//
// Every symlink component is refused, including the file itself. os.Root blocks
// a link that escapes the worktree but follows one pointing elsewhere inside
// it; accepting the leaf would let `.claude/settings.json -> ../victim.json`
// redirect both the merge read and the subsequent write.
//
// An earlier revision of this type deliberately allowed a symlinked leaf, on the
// grounds that pointing `.claude/settings.json` at a dotfile repo is a real
// setup Entire has no business breaking. That was reconsidered, and the reason
// is worth keeping: the merge READ pulls the target's contents into what Entire
// then writes, and the write is a rename, which replaces the user's link with a
// regular file rather than following it. Both happen silently. Refusing is the
// legible version of the same outcome.
//
// The setup still works, because the thing that makes a link dangerous here is
// that it arrived with the checkout. A developer who wants one keeps it out of
// the repository — `git rm --cached .claude/settings.json` and a .gitignore
// entry — and manages it locally, which is what a dotfile workflow does anyway.
type HookConfigFile struct {
	root *os.Root
	// name is root-relative, for I/O. It is NOT worktree-relative: when a
	// vouched symlinked agent directory was followed, the root is anchored at
	// that directory's target and name has lost the components consumed getting
	// there.
	name string
	// relName is the worktree-relative name, for every DECISION about the path
	// as opposed to every access through it. Two coordinates for one file, the
	// same split entiredir.Name draws, and RemoveDir is why it exists: it
	// reasons about which directory it is allowed to delete, and doing that on
	// the root-relative name let anchoring change the answer.
	relName string
	path    string
}

// HookConfigLocator is implemented by an agent whose Entire hook configuration
// is a file inside the worktree: it returns the same worktree-relative,
// slash-separated path the agent passes to OpenHookConfig.
//
// It exists for the callers that must reason about that path WITHOUT doing I/O
// on it. Doctor's symlink diagnosis is the first: the directories BETWEEN an
// agent's own directory and its config file — `.pi/extensions`,
// `.pi/extensions/entire`, `.opencode/plugins` — are created by Entire and
// appear in no other registry, because ProtectedDirs names what the AGENT owns
// (`.pi`, `.opencode`) and stops there. Deriving them from a hand-kept list in
// the caller is how two of them came to be unchecked in the first place.
//
// Optional: an agent whose hooks are not a worktree file (an external plugin
// declaring them in its manifest) does not implement it. See
// TestAllHookConfigRelPaths_CoversEveryWorktreeConfigAgent for the ones that
// must.
type HookConfigLocator interface {
	// HookConfigRelPath returns the config file's path relative to the worktree
	// root, slash-separated, exactly as passed to OpenHookConfig.
	HookConfigRelPath() string
}

// OpenHookConfig returns the hook-config file at relPath inside worktreeRoot.
//
// relPath is slash-separated and relative to the worktree root
// (".cursor/hooks.json"). The directory does not need to exist: Read reports a
// missing file the way os.ReadFile does, and Write creates the parents.
func OpenHookConfig(worktreeRoot, relPath string) (*HookConfigFile, error) {
	// Validate against the worktree root first, so a relPath that escapes is
	// rejected before anything is resolved. AnchorWorktreePath re-anchors only
	// on directories the user vouched for by name, but it should never be the
	// thing deciding whether the path was well formed.
	name, err := worktreedir.Name(worktreeRoot, relPath)
	if err != nil {
		return nil, fmt.Errorf("resolve hook config path: %w", err)
	}
	display := filepath.Join(worktreeRoot, filepath.FromSlash(name))

	// Two bases, one behaviour below. The ordinary case anchors on the worktree
	// root and every agent directory stays a name inside it, refusable by
	// MkdirAllNoSymlink. A vouched symlinked directory anchors on its resolved
	// target instead, and everything below it is still a name inside a root.
	root, inner, err := OpenAnchoredRoot(worktreeRoot, name)
	if err != nil {
		return nil, fmt.Errorf("resolve hook config path: %w", err)
	}
	return &HookConfigFile{
		root:    root,
		name:    inner,
		relName: name,
		// The link's own path, not the resolved one. It is what the user typed,
		// what doctor prints, and what the agents write into their own config,
		// where following the link is the agent's business and works.
		path: display,
	}, nil
}

// Path is the file's absolute path, for messages and for the agent config that
// has to name it. It is not an invitation to do I/O on the result.
func (f *HookConfigFile) Path() string { return f.path }

// Read returns the file's contents. A missing file is reported unwrapped so
// callers can classify it with os.IsNotExist, which is how every agent's
// install path decides between "merge into existing" and "write fresh".
func (f *HookConfigFile) Read() ([]byte, error) {
	return osroot.ReadFileNoFollow(f.root, f.name) //nolint:wrapcheck // see doc comment
}

// Exists reports whether the file is present at a path Entire will read.
//
// A symlinked parent directory counts as absent rather than as an error, since
// the signature has nowhere to put one. That is the useful answer: every caller
// uses this to choose between merging into an existing file and writing a fresh
// one, and Write refuses the same path with a message that names the link.
func (f *HookConfigFile) Exists() bool {
	info, err := osroot.LstatNoSymlinks(f.root, f.name)
	return err == nil && info.Mode()&os.ModeSymlink == 0
}

