  19	type worktreeSetupIssue struct {
  20		ConfiguredWorktree string
  21		MissingSettings    bool
  22		MissingClaudeHooks bool
  23	}
  24	
  25	func inspectWorktreeSetup(ctx context.Context) *worktreeSetupIssue {
  26		currentRoot, err := paths.WorktreeRoot(ctx)
  27		if err != nil {
  28			return nil
  29		}
  30	
  31		project, local, err := settings.FilesPresent(ctx)
  32		if err != nil {
  33			return nil
  34		}
  35		hasSettings := project || local
  36		if hasSettings {
  37			currentSettings, loadErr := LoadEntireSettings(ctx)
  38			if loadErr != nil || !currentSettings.Enabled {
  39				return nil
  40			}
  41		}
  42	
  43		hasClaudeHooks, err := (&claudecode.ClaudeCodeAgent{}).AreHooksInstalled(ctx)
  44		if err != nil {
  45			return nil
  46		}
  47		if hasSettings && hasClaudeHooks {
  48			return nil
  49		}
  50	
  51		for _, sibling := range siblingWorktrees(ctx, currentRoot) {
  52			if !settings.IsSetUpAndEnabledForWorktreeRoot(ctx, sibling) {
  53				continue
  54			}
  55			hasHooks, hookErr := claudecode.AreHooksInstalledInWorktree(ctx, sibling)
  56			if hookErr == nil && hasHooks {
  57				return &worktreeSetupIssue{
  58					ConfiguredWorktree: sibling,
  59					MissingSettings:    !hasSettings,
  60					MissingClaudeHooks: !hasClaudeHooks,
  61				}
  62			}
  63		}
  64		return nil
  65	}
  66	
  67	func siblingWorktrees(ctx context.Context, currentRoot string) []string {
  68		ctx, cancel := context.WithTimeout(ctx, 5*time.Second)
  69		defer cancel()
  70	
  71		cmd := exec.CommandContext(ctx, "git", "worktree", "list", "--porcelain", "-z")
  72		cmd.Dir = currentRoot
  73		output, err := cmd.Output()
  74		if err != nil {
  75			return nil
  76		}
  77		return parseSiblingWorktrees(output, normalizeWorktreePath(currentRoot))
  78	}
  79	
  80	func parseSiblingWorktrees(porcelain []byte, currentRoot string) []string {
  81		var worktrees []string
  82		var path string
  83		prunable := false
  84		for _, field := range bytes.Split(porcelain, []byte{0}) {
  85			line := string(field)
  86			switch {
  87			case line == "":
  88				if path != "" && !prunable && normalizeWorktreePath(path) != currentRoot {
  89					worktrees = append(worktrees, path)
  90				}
  91				path = ""
  92				prunable = false
  93			case strings.HasPrefix(line, "worktree "):
  94				path = strings.TrimPrefix(line, "worktree ")
  95			case line == "prunable" || strings.HasPrefix(line, "prunable "):
