// LoadForWorktreeRoot is Load for an explicit worktree root instead of the
// process working directory. Code that already holds a repository — a doctor
// repair, a test fixture — must read that repository's settings, not whatever
// the current directory happens to be inside.
func LoadForWorktreeRoot(ctx context.Context, worktreeRoot string) (*EntireSettings, error) {
	return loadForWorktreeRoot(ctx, worktreeRoot)
}

func loadForWorktreeRoot(ctx context.Context, worktreeRoot string) (*EntireSettings, error) {
	settingsFileAbs, localSettingsFileAbs := worktreeSettingsPaths(worktreeRoot)
	preferencesFileAbs := ""
	if path, prefErr := clonePreferencesPathForWorktreeRoot(ctx, worktreeRoot); prefErr == nil {
		preferencesFileAbs = path
	} else {
		logging.Debug(ctx, "clone preferences path unresolved; skipping preferences layer",
			slog.String("error", prefErr.Error()))
	}
	return loadMergedSettings(ctx, settingsFileAbs, preferencesFileAbs, localSettingsFileAbs)
}

func clonePreferencesPathForWorktreeRoot(ctx context.Context, worktreeRoot string) (string, error) {
	cmd := exec.CommandContext(ctx, "git", "-C", worktreeRoot, "rev-parse", "--git-common-dir")
	output, err := cmd.Output()
	if err != nil {
		return "", fmt.Errorf("resolve git common dir: %w", err)
	}

	commonDir := strings.TrimSpace(string(output))
	if !filepath.IsAbs(commonDir) {
		commonDir = filepath.Join(worktreeRoot, commonDir)
	}
	return filepath.Join(filepath.Clean(commonDir), ClonePreferencesFile), nil
}

// worktreeRootOfSettingsFile recovers the worktree root a settings path was
// built from: settingsAbsPaths joins <root>/.entire/<file>, so the root is two
// levels up. Used only as the KEY the vouched-symlink policy is scoped by, never
// as a base for I/O, so the derived-path rule in CLAUDE.md does not apply -- an
// inconsistent key costs a refused symlink, which is the safe direction.
func worktreeRootOfSettingsFile(settingsFileAbs string) string {
	if settingsFileAbs == "" {
		return ""
	}
	return filepath.Dir(filepath.Dir(settingsFileAbs))
}

func loadMergedSettings(ctx context.Context, settingsFileAbs, preferencesFileAbs, localSettingsFileAbs string) (*EntireSettings, error) {
	// Load base settings
	settings, err := loadFromFile(settingsFileAbs)
	if err != nil {
		return nil, fmt.Errorf("reading settings file: %w", err)
	}

	var preferences *ClonePreferences
	if preferencesFileAbs != "" {
		preferences, err = loadClonePreferencesFromFile(preferencesFileAbs)
		if err != nil {
			return nil, fmt.Errorf("reading clone preferences file: %w", err)
		}
		applyClonePreferences(settings, preferences)
	}

	// Apply local overrides if they exist — but only from a file that is
	// genuinely local. See localLayerTrackedReason.
	localData, err := readConfined(localSettingsFileAbs)
	if err != nil {
		if !errors.Is(err, fs.ErrNotExist) {
			return nil, fmt.Errorf("reading local settings file: %w", err)
		}
		// Local file doesn't exist, continue without overrides
	} else if classifyLocalSettings(ctx, localSettingsFileAbs) == localTracked {
		// Dropped only on PROOF that the file is tracked. Discarding every
		// local setting because a repository could not be read would be a
		// worse failure than the one being guarded against — the exec-bearing
		// OPF command applies the stricter policy for itself.
		settings.localLayerRejection = localLayerTrackedReason
		localData = nil
	} else if err := mergeJSON(settings, localData); err != nil {
		return nil, fmt.Errorf("merging local settings: %w", err)
	}

	// openai_privacy_filter.command is executed, so it is honored only from a
	// local file positively verified as this developer's own. external_agents
	// grants execution of every entire-agent-* binary on $PATH, so it gets the
	// same gate. Agent instruction fields (investigate.always_prompt, review
	// prompts) are appended verbatim to prompts of agents spawned with
	// approval checks disabled, so they get the same provenance requirement,
	// with clone-local preferences as an additional trusted layer.
	enforceOPFCommandTrust(ctx, settings, localSettingsFileAbs, localData)
	enforceExternalAgentsTrust(ctx, settings, localSettingsFileAbs, localData)
	enforceAgentPromptTrust(ctx, settings, localSettingsFileAbs, localData, preferences)
	// allow_symlinked_agent_dirs decides where Entire writes an agent's hook
	// config, so it gets the same gate, and then installs the surviving set as
	// the process-wide policy.
	enforceSymlinkedAgentDirsTrust(ctx, settings, localSettingsFileAbs, localData)
	applyVouchedAgentDirs(settings, worktreeRootOfSettingsFile(settingsFileAbs))

	// Re-validate after merge. Individual files are validated by loadFromFile,
	// but mergeJSON patches fields independently and can produce combinations
	// (e.g. model without provider when the local override sets only a model
	// on top of a base with no provider) that neither file alone contained.
	if err := settings.SummaryGeneration.Validate(); err != nil {
		return nil, fmt.Errorf("merged settings invalid: %w", err)
	}

	if err := validateScannerSettings(settings); err != nil {
		return nil, fmt.Errorf("merged settings invalid: %w", err)
	}

	return settings, nil
}

// LoadFromFile loads settings from a specific file path without merging local overrides.
// Returns default settings if the file doesn't exist.
// Use this when you need to display individual settings files separately.
func LoadFromFile(filePath string) (*EntireSettings, error) {
	return loadFromFile(filePath)
}
	if _, _, underEntire := entiredir.Split(filePath); !underEntire {
		return readConfinedOutsideEntire(filePath)
	}

	// A relative path is resolved against the process's directory, which is what
	// "relative" means and what LoadFromFile's callers pass deliberately. The
	// anchor rule entiredir enforces is about code that DERIVES a .entire path
	// (see settingsAbsPaths, which now goes through entiredir.PathTo); it is not
	// a reason to refuse a path a caller handed us.
	filePath, err := filepath.Abs(filePath)
	if err != nil {
		return nil, fmt.Errorf("resolve settings path: %w", err)
	}

	root, name, err := entiredir.OpenPathForRead(filePath)
	if err != nil {
		return nil, fmt.Errorf("open settings dir: %w", err)
	}
	return readConfinedIn(root, name, filePath)
}

// readConfinedOutsideEntire reads the clone-preferences file, which lives in the
// git common dir rather than under .entire, through that directory's shared
// root.
//
// The fallback anchors on the file's own parent, and that is the one shape this
// codebase otherwise refuses — see the "an os.Root's base must be a trusted
// path" rule. It is allowed here for the same reason tokenstore's is: the paths
// that reach it are ones the CALLER named (the explicit-path settings tests, and
// LoadFromFile's callers), so their parent directory is the caller's choice too
// and there is no separate trusted base to prefer. It never applies to a path
// Entire derived — those are placed under a common dir by clonePreferencesRoot
// above, or under .entire by readConfined's other branch.
func readConfinedOutsideEntire(filePath string) ([]byte, error) {
	if root, name, err := clonePreferencesRoot(filePath); err == nil {
		return readConfinedIn(root, name, filePath)
	}

	root, err := os.OpenRoot(filepath.Dir(filePath))
	if err != nil {
		return nil, fmt.Errorf("open settings dir: %w", err)
	}
	defer root.Close()

	return readConfinedIn(root, filepath.Base(filePath), filePath)
}

// readConfinedIn is the one read every readConfined branch performs: refuse a
// symlink, open, re-validate against the race, then read.
//
// It exists so the refusal cannot be true of one branch and not another. It was
// briefly true of only one: the .entire branch read straight through
// osroot.ReadFile, which follows an in-root symlink silently — precisely the
// `.entire/settings.local.json -> planted.json` case the check exists for.
//
// filePath is carried alongside name only for the error text: name is relative
// to a root the caller cannot see, and the user needs the path they can act on.
func readConfinedIn(root *os.Root, name, filePath string) ([]byte, error) {
	data, err := osroot.ReadFileNoFollow(root, name)
	if err != nil {
		if errors.Is(err, osroot.ErrSymlinkedPath) {
			//nolint:wrapcheck // sentinel surfaces verbatim for the caller's errors.Is; callers add the reading-context prefix
			return nil, paths.SymlinkedEntryError(filePath)
		}
		return nil, fmt.Errorf("read settings file %s: %w", filePath, err)
	}
	return data, nil
}

// writeConfinedAtomic is readConfined's write half: an atomic write through the
// shared .entire root, or through the git common dir's root for the clone
// preferences file. It creates the parent directory, which for a .entire path
// means the root itself.
//
// The non-.entire branch used to be a plain os.MkdirAll plus an unrooted atomic
// write, which made the two halves asymmetric for no reason: readConfined
// already resolved that same file through clonePreferencesRoot. A write is the
// half that matters more, so it gets the same root.
func writeConfinedAtomic(filePath string, data []byte, perm fs.FileMode) error {
	// Same branch-on-location rule as readConfined.
	if _, _, underEntire := entiredir.Split(filePath); !underEntire {
		return writeClonePreferencesAtomic(filePath, data, perm)
	}

	// Same relative-path handling as readConfined.
	filePath, err := filepath.Abs(filePath)
	if err != nil {
		return fmt.Errorf("resolve settings path: %w", err)
	}

	root, name, err := entiredir.OpenPath(filePath)
"}

{"chunk_id":"a8f55d","wall_time_seconds":0.000002417,"exit_code":0,"original_token_count":1608,"output":"// Package worktreedir owns access to the files of the working tree itself.
//
// It is the third of Entire's three anchors, alongside entiredir (.entire) and
// gitdir (the git common dir), and the loosest of them: a root here contains
// operations to the repository rather than to a directory Entire owns. That is
// still worth having, because the paths that reach these reads and writes are
// not Entire's own:
//
//   - Checkpoint writes read working files named by `git status` output, on the
//     hook path, to turn them into blobs.
//   - Rewind writes working files named by git TREE ENTRIES out of a checkpoint,
//     which may have been fetched from a remote. Its restore half already opened
//     a root for exactly this reason; the reads beside it did not.
//   - Diff-stat and gather read working files named from status output too.
//
// A root makes "cannot leave the repository" a property of the handle rather
// than of each caller remembering to validate. It is not a substitute for the
// tree-path validation those callers do — normalizeRepoRelativeTreePath still
// rejects names that are not repo-relative before they are used as git paths —
// it is the layer underneath it.
package worktreedir

import (
	"context"
	"errors"
	"fmt"
	"os"
	"path/filepath"

	"github.com/entireio/cli/cmd/entire/cli/osroot"
	"github.com/entireio/cli/cmd/entire/cli/paths"
)

// Open returns the shared *os.Root over the current worktree root. The returned
// root is owned by the registry and shared with every other caller; do not close
// it.
func Open(ctx context.Context) (*os.Root, error) {
	root, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return nil, fmt.Errorf("resolve worktree root: %w", err)
	}
	return OpenAt(root)
}

// OpenAt is Open for an explicit worktree root, for callers that resolved one
// already or that act on a worktree other than the current directory.
func OpenAt(worktreeRoot string) (*os.Root, error) {
	if worktreeRoot == "" {
		return nil, errors.New("worktreedir: worktree root is required")
	}
	abs, err := filepath.Abs(worktreeRoot)
	if err != nil {
		return nil, fmt.Errorf("resolve %s: %w", worktreeRoot, err)
	}
	return osroot.Shared(abs) //nolint:wrapcheck // Shared names the directory and returns a missing one unwrapped
}

// Name converts a path inside the worktree to a name relative to its root,
// accepting either an absolute path or one already relative to the root.
//
// Git hands out slash-separated repo-relative paths and Entire assembles
// absolute ones from them; this is the single conversion back, so callers stop
// joining a root path onto a git path and reading the result.
func Name(worktreeRoot, p string) (string, error) {
	// filepath.IsLocal, the single primitive os.Root itself uses one layer down,
	// rather than an IsAbs/VolumeName pair. Windows has two forms that are
	// neither absolute nor volume-prefixed yet do not name anything inside the
	// worktree: the drive-relative "C:foo", which IsAbs reports false for while
	// filepath.Join drops the base directory when the appended element carries a
	// volume; and the rooted-relative "\foo", where volumeNameLen is 0 because a
	// single leading backslash is neither a volume nor a UNC prefix. Sending
	// both down the absolute branch makes filepath.Rel reject them, which is the
	// answer this containment check exists to give. IsLocal also rejects "..",
	// which the traversal check below covers anyway, and the Windows reserved
	// device names, which nothing here wants either.
	//
	// os.Root rejects such a name one layer down, so neither is a reachable
	// escape today. They are closed anyway because Name exists to answer "is
	// this inside the worktree?" independently of the caller, and
	// readWorktreeFileSafely feeds it paths that arrive from the API.
	if filepath.IsLocal(p) {
		cleaned := filepath.ToSlash(filepath.Clean(filepath.FromSlash(p)))
		if cleaned == "." || paths.IsRelativeTraversal(cleaned) {
			return "", fmt.Errorf("%q does not name a file in the worktree", p)
		}
		return cleaned, nil
	}
	base, err := filepath.Abs(worktreeRoot)
	if err != nil {
		return "", fmt.Errorf("resolve %s: %w", worktreeRoot, err)
	}
	rel, err := filepath.Rel(base, p)
	if err != nil || rel == "." || paths.IsRelativeTraversal(rel) {
		return "", fmt.Errorf("%q is not inside %q", p, worktreeRoot)
	}
	return filepath.ToSlash(rel), nil
}

// NameFollowingLinks is Name for a path that may itself be, or sit below, a
// symlink: it resolves the link first and then answers for the target.
//
// os.Root refuses an ABSOLUTE symlink target unconditionally, including one
// resolving inside the root, so a root alone cannot express "follow a link that
// stays in the worktree, refuse one that leaves". That distinction is what a
// user-owned working-tree file needs — pointing vercel.json at a monorepo's
// shared config is a real setup, and it is written absolute as often as
// relative — while Entire's own trees (.entire, an agent's hook config) refuse
// a link either way and must not use this.
//
// The name returned is worktree-relative and symlink-free, so the caller's read
// still goes through the root: a link repointed between the resolve and the read
// changes which in-worktree file is read and cannot escape the worktree.
//
// A dangling link reports os.ErrNotExist, matching what os.Stat gives for one.
func NameFollowingLinks(worktreeRoot, p string) (string, error) {
	base, err := filepath.Abs(worktreeRoot)
	if err != nil {
		return "", fmt.Errorf("resolve %s: %w", worktreeRoot, err)
	}
	target := p
	if !filepath.IsAbs(target) {
		target = filepath.Join(base, filepath.FromSlash(target))
	}
	resolved, err := filepath.EvalSymlinks(target)
	if err != nil {
	if err != nil {
		return "", fmt.Errorf("resolve %s: %w", p, err)
	}
	// The BASE has to be resolved too, against the same rules. Otherwise every
	// repository living below a symlinked component is judged from a path that
	// no longer matches its own resolved children: on macOS /var is a link to
	// /private/var, so a worktree under /var/folders/... would have each of its
	// own files reported as outside itself. The relative answer is unaffected by
	// which spelling the caller's root was opened under.
	resolvedBase, err := filepath.EvalSymlinks(base)
	if err != nil {
		return "", fmt.Errorf("resolve %s: %w", worktreeRoot, err)
	}
	return Name(resolvedBase, resolved)
}
"}

