236		rewrittenLocalTip, remoteTip plumbing.Hash,
237		originalToRewritten map[plumbing.Hash]plumbing.Hash,
238	) (rewritten, original plumbing.Hash, found bool, err error) {
239		remoteTrees := make(map[plumbing.Hash]struct{})
240		remoteHistory, err := repo.Log(&git.LogOptions{From: remoteTip})
241		if err != nil {
242			return plumbing.ZeroHash, plumbing.ZeroHash, false, fmt.Errorf("log remote checkpoint history: %w", err)
243		}
