245		if walkErr := remoteHistory.ForEach(func(commit *object.Commit) error {
246			if err := ctx.Err(); err != nil {
247				return fmt.Errorf("scan remote checkpoint trees: %w", err)
248			}
249			remoteTrees[commit.TreeHash] = struct{}{}
250			return nil
251		}); walkErr != nil {
252			return plumbing.ZeroHash, plumbing.ZeroHash, false, fmt.Errorf("walk remote checkpoint history: %w", walkErr)
253		}
254	
255		rewrittenToOriginal := make(map[plumbing.Hash]plumbing.Hash, len(originalToRewritten))
256		for oldHash, newHash := range originalToRewritten {
257			rewrittenToOriginal[newHash] = oldHash
258		}
259		localHistory, err := repo.Log(&git.LogOptions{From: rewrittenLocalTip})
260		if err != nil {
261			return plumbing.ZeroHash, plumbing.ZeroHash, false, fmt.Errorf("log rewritten local checkpoint history: %w", err)
262		}
263		defer localHistory.Close()
264		walkErr := localHistory.ForEach(func(commit *object.Commit) error {
265			if err := ctx.Err(); err != nil {
266				return fmt.Errorf("scan rewritten local checkpoint trees: %w", err)
267			}
268			if _, exists := remoteTrees[commit.TreeHash]; !exists {
269				return nil
270			}
271			oldHash, exists := rewrittenToOriginal[commit.Hash]
272			if !exists {
273				return fmt.Errorf("rewritten commit %s has no original", commit.Hash)
274			}
275			rewritten = commit.Hash
276			original = oldHash
277			found = true
278			return errStop
279		})
280		if walkErr != nil && !errors.Is(walkErr, errStop) {
281			return plumbing.ZeroHash, plumbing.ZeroHash, false, fmt.Errorf("walk rewritten local checkpoint history: %w", walkErr)
282		}
283		return rewritten, original, found, nil
284	}
