   603	func resolveTargetForTokenAuth(ctx context.Context, target string) (string, string) {
   604		if target == "" || isLocalPath(target) {
   605			return target, ""
   606		}
   607	
   608		rawURL := target
   609		if !IsURL(target) {
   610			var err error
   611			rawURL, err = GetRemoteURL(ctx, target)
   612			if err != nil {
   613				return target, ""
   614			}
   615		}
   616	
   617		info, err := ParseURL(rawURL)
   618		if err != nil {
   619			return target, ""
   620		}
   621	
   622		if info.Protocol == ProtocolSSH {
   623			if httpsURL, ok := deriveTokenOriginURL(rawURL); ok {
   624				return httpsURL, ProtocolHTTPS
   625			}
   626			return target, ProtocolSSH
   627		}
   628	
   629		return target, info.Protocol
   630	}
   631	
   632	// replaceFirstPositional returns a copy of args with the first non-flag
   633	// argument after args[0] (the git subcommand) replaced by newTarget. Callers
   634	// use this to rewrite a remote name/URL after resolution without mutating the
   635	// original slice.
   636	func replaceFirstPositional(args []string, newTarget string) []string {
   637		out := make([]string, len(args))
   638		copy(out, args)
   639		for i := 1; i < len(out); i++ {
   640			if !strings.HasPrefix(out[i], "-") {
   641				out[i] = newTarget
   642				return out
   643			}
   644		}
   645		return out
   646	}
   647	
   648	// extractRemoteFromArgs finds the remote URL or name from git command args.
   649	// It skips the subcommand (first arg) and any flags (args starting with "-"),
   650	// returning the first positional argument, which is the remote for push/fetch/ls-remote.
   651	func extractRemoteFromArgs(args []string) string {
   652		if len(args) < 2 {
   653			return ""
   654		}
   655		// Skip subcommand (e.g., "push", "fetch", "ls-remote").
   656		for _, arg := range args[1:] {
   657			if !strings.HasPrefix(arg, "-") {
   658				return arg
   659			}
   660		}
   661		return ""
   662	}
   663	
   664	// appendCheckpointTokenEnv appends GIT_CONFIG_COUNT-based env vars to inject
   665	// an Authorization header into git HTTP requests. The token is sent as a Basic
   666	// credential with the format "x-access-token:<token>" (base64-encoded), which
   667	// is compatible with GitHub's token authentication.
   668	//
   669	// Existing GIT_CONFIG_KEY_*/GIT_CONFIG_VALUE_* entries are preserved; the new
   670	// http.extraHeader entry is appended at the next free index and
   671	// GIT_CONFIG_COUNT is updated accordingly. This keeps caller-injected git
   672	// config (e.g., safe.directory, custom CA settings) intact.
   673	func appendCheckpointTokenEnv(baseEnv []string, token string) []string {
   674		existingCount := 0
   675		for _, e := range baseEnv {
   676			rest, ok := strings.CutPrefix(e, "GIT_CONFIG_COUNT=")
   677			if !ok {
   678				continue
   679			}
   680			if n, err := strconv.Atoi(rest); err == nil && n > 0 {
   681				existingCount = n
   682			}
   683		}
   684	
   685		// Strip the old GIT_CONFIG_COUNT entry (we'll emit a new one) but keep
   686		// GIT_CONFIG_KEY_*/GIT_CONFIG_VALUE_* entries in place.
   687		filtered := make([]string, 0, len(baseEnv)+3)
   688		for _, e := range baseEnv {
   689			if strings.HasPrefix(e, "GIT_CONFIG_COUNT=") {
   690				continue
   691			}
   692			filtered = append(filtered, e)
   693		}
   694	
   695		idx := existingCount
   696		encoded := base64.StdEncoding.EncodeToString([]byte("x-access-token:" + token))
   697		return append(filtered,
   698			fmt.Sprintf("GIT_CONFIG_COUNT=%d", existingCount+1),
   699			fmt.Sprintf("GIT_CONFIG_KEY_%d=http.extraHeader", idx),
   700			fmt.Sprintf("GIT_CONFIG_VALUE_%d=Authorization: Basic %s", idx, encoded),
   701		)
   702	}
   703	
   704	// isValidToken returns false if the token contains control characters (bytes < 0x20
   705	// or 0x7F). This prevents HTTP header injection via CR/LF or other control chars
   706	// embedded in the token value.
   707	func isValidToken(token string) bool {
   708		for _, b := range []byte(token) {
   709			if b < 0x20 || b == 0x7F {
   710				return false
   711			}
   712		}
   713		return true
   714	}
