   745	// disableTerminalPrompt sets GIT_TERMINAL_PROMPT=0 on the command,
   746	// initializing cmd.Env from os.Environ() if nil.
   747	func disableTerminalPrompt(cmd *exec.Cmd) {
   748		if cmd.Env == nil {
   749			cmd.Env = os.Environ()
   750		}
   751		cmd.Env = append(cmd.Env, "GIT_TERMINAL_PROMPT=0")
   752	}

