   648	// extractRemoteFromArgs finds the remote URL or name from git command args.
   649	// It skips the subcommand (first arg) and any flags (args starting with "-"),
   650	// returning the first positional argument, which is the remote for push/fetch/ls-remote.
   651	func extractRemoteFromArgs(args []string) string {
   652		if len(args) < 2 {
   653			return ""
   654		}
   655		// Skip subcommand (e.g., "push", "fetch", "ls-remote").
   656		for _, arg := range args[1:] {
   657			if !strings.HasPrefix(arg, "-") {
   658				return arg
   659			}
   660		}
   661		return ""
   662	}
