   664	// appendCheckpointTokenEnv appends GIT_CONFIG_COUNT-based env vars to inject
   665	// an Authorization header into git HTTP requests. The token is sent as a Basic
   666	// credential with the format "x-access-token:<token>" (base64-encoded), which
   667	// is compatible with GitHub's token authentication.
   668	//
   669	// Existing GIT_CONFIG_KEY_*/GIT_CONFIG_VALUE_* entries are preserved; the new
   670	// http.extraHeader entry is appended at the next free index and
   671	// GIT_CONFIG_COUNT is updated accordingly. This keeps caller-injected git
   672	// config (e.g., safe.directory, custom CA settings) intact.
   673	func appendCheckpointTokenEnv(baseEnv []string, token string) []string {
   674		existingCount := 0
   675		for _, e := range baseEnv {
   676			rest, ok := strings.CutPrefix(e, "GIT_CONFIG_COUNT=")
   677			if !ok {
   678				continue
   679			}
   680			if n, err := strconv.Atoi(rest); err == nil && n > 0 {
   681				existingCount = n
   682			}
   683		}
   684	
   685		// Strip the old GIT_CONFIG_COUNT entry (we'll emit a new one) but keep
   686		// GIT_CONFIG_KEY_*/GIT_CONFIG_VALUE_* entries in place.
   687		filtered := make([]string, 0, len(baseEnv)+3)
   688		for _, e := range baseEnv {
   689			if strings.HasPrefix(e, "GIT_CONFIG_COUNT=") {
   690				continue
   691			}
   692			filtered = append(filtered, e)
   693		}
   694	
   695		idx := existingCount
   696		encoded := base64.StdEncoding.EncodeToString([]byte("x-access-token:" + token))
   697		return append(filtered,
   698			fmt.Sprintf("GIT_CONFIG_COUNT=%d", existingCount+1),
   699			fmt.Sprintf("GIT_CONFIG_KEY_%d=http.extraHeader", idx),
   700			fmt.Sprintf("GIT_CONFIG_VALUE_%d=Authorization: Basic %s", idx, encoded),
   701		)
   702	}
