   704	// isValidToken returns false if the token contains control characters (bytes < 0x20
   705	// or 0x7F). This prevents HTTP header injection via CR/LF or other control chars
   706	// embedded in the token value.
   707	func isValidToken(token string) bool {
   708		for _, b := range []byte(token) {
   709			if b < 0x20 || b == 0x7F {
   710				return false
   711			}
   712		}
   713		return true
   714	}
