   716	// resolvePushCommandTarget returns the target to pass to git push. When a
   717	// dedicated checkpoint_remote is configured, the checkpoint URL is returned so
   718	// the push is routed to the separate checkpoint repo. Otherwise the remote
   719	// name is returned unchanged so git uses its own config, updates the
   720	// refs/remotes/<name>/<branch> tracking ref, and subsequent calls can use that
   721	// tracking ref to skip redundant pushes.
   722	//
   723	// SSH→HTTPS coercion for token auth is handled by newCommand, which rewrites
   724	// the command args or injects per-host config, rather than being baked into
   725	// the target here.
   726	func resolvePushCommandTarget(ctx context.Context, target string) (string, error) {
   727		if target == "" || IsURL(target) || isLocalPath(target) {
   728			return target, nil
   729		}
   730	
   731		pushTarget, enabled, err := PushURL(ctx, target)
   732		if err != nil {
   733			return "", err
   734		}
   735		if !enabled || pushTarget == "" {
   736			return target, nil
   737		}
   738		return pushTarget, nil
   739	}
