   373	// isFileMode reports whether a tree entry is a file whose content is a blob.
   374	// filemode.Deprecated (0100664) is a regular file too: go-git documents that it
   375	// "should be treated as Regular", and a metadata.json carrying that mode would
   376	// otherwise be invisible to both the scan and the rewrite.
   377	func isFileMode(mode filemode.FileMode) bool {
   378		return mode == filemode.Regular || mode == filemode.Executable || mode == filemode.Deprecated
   379	}
   380	
   381	// contentReachable reports whether some commit reachable from tip carries
   382	// exactly the tree of commit target. On the cumulative checkpoint branch equal
   383	// trees mean equal checkpoint content, so this answers "does tip's history
   384	// already contain everything target has?" independently of commit hashes —
   385	// which differ across independent rewrites when commit signing is on.
   386	func contentReachable(repo *git.Repository, tip, target plumbing.Hash) (bool, error) {
   387		if tip.IsZero() || target.IsZero() {
   388			return false, nil
   389		}
   390		tc, err := repo.CommitObject(target)
   391		if err != nil {
   392			return false, fmt.Errorf("load commit %s: %w", target, err)
   393		}
   394		iter, err := repo.Log(&git.LogOptions{From: tip})
   395		if err != nil {
   396			return false, fmt.Errorf("log %s: %w", tip, err)
   397		}
   398		defer iter.Close()
   399		found := false
   400		walkErr := iter.ForEach(func(c *object.Commit) error {
   401			if c.TreeHash.Equal(tc.TreeHash) {
   402				found = true
   403				return errStop
   404			}
   405			return nil
   406		})
   407		if walkErr != nil && !errors.Is(walkErr, errStop) {
   408			return false, fmt.Errorf("walk history of %s: %w", tip, walkErr)
   409		}
   410		return found, nil
   411	}
